<script setup>
import { computed } from 'vue'
import Chart from 'primevue/chart'
import Button from 'primevue/button'
import { Plus, ArrowUpRight, Calendar, RefreshCw, CircleCheck, Layers, Clock } from 'lucide-vue-next'
import { useToast } from 'primevue/usetoast'
import { projects } from '../../stores/projects'
import { session } from '../../stores/session'
import { statuses, calendar, due, initials } from '../../utils/format'
import ProjectState from '../../components/project/ProjectState.vue'
import ProjectInsights from '../../components/project/ProjectInsights.vue'
import ActivityList from '../../components/common/ActivityList.vue'
const dashboard=computed(()=>projects.state.dashboard), project=computed(()=>projects.active.value), leader=computed(()=>session.state.team?.role==='LEADER'), toast=useToast()
const styles=getComputedStyle(document.documentElement), colors=['--status-todo','--status-in_progress','--status-review','--status-done'].map(key=>styles.getPropertyValue(key).trim())
const chartData=computed(()=>({labels:statuses.map(s=>s.label),datasets:[{data:statuses.map(s=>dashboard.value?.statuses[s.value] || 0),backgroundColor:colors,borderWidth:0,hoverOffset:5}]}))
const chartOptions={responsive:true,maintainAspectRatio:false,cutout:'78%',plugins:{legend:{display:false},tooltip:{backgroundColor:styles.getPropertyValue('--tf-surface-elevated').trim(),titleColor:styles.getPropertyValue('--tf-text').trim(),bodyColor:styles.getPropertyValue('--tf-text-muted').trim(),padding:12}},animation:window.matchMedia('(prefers-reduced-motion: reduce)').matches ? false : {duration:250}}
async function refresh() { try { await projects.refresh() } catch(e) { toast.add({severity:'error',summary:e.friendly,life:4000}) } }
</script>
<template><ProjectState><div class="page-heading project-heading"><div><span class="eyebrow">PROJECT OVERVIEW</span><h1>{{ project.name }}</h1><p>{{ project.description || 'A shared goal. Clear ownership. Work that moves forward.' }}</p><div class="project-context"><span><Calendar :size="13" />{{ calendar(project.deadline) }}</span><span><Layers :size="13" />{{ session.state.team.member_count }} teammates</span></div></div><div class="d-flex gap-2"><Button aria-label="Refresh project" severity="secondary" :loading="projects.state.loading" @click="refresh"><RefreshCw :size="16" /></Button><Button v-if="leader" label="Create task" @click="projects.state.createTask=true"><template #icon><Plus :size="16" /></template></Button></div></div><div class="dashboard-grid"><section class="progress-panel panel"><div class="section-heading"><span class="eyebrow">THE BIG PICTURE</span><RouterLink to="/board">Open board <ArrowUpRight :size="14" /></RouterLink></div><div class="progress-panel-content"><div class="progress-ring" :style="{'--progress':`${dashboard.progress*3.6}deg`}"><div><strong>{{ dashboard.progress }}<span>%</span></strong><small>PROJECT PROGRESS</small></div></div><div class="progress-copy"><h2>{{ dashboard.total ? dashboard.progress===100 ? 'The work is complete.' : 'Every step moves you forward.' : 'Your next chapter starts here.' }}</h2><p>{{ dashboard.total ? `${dashboard.statuses.DONE} of ${dashboard.total} tasks completed. Progress is the average of all task progress values.` : 'Create your first task to start tracking real project progress.' }}</p><div class="progress-meta"><span><CircleCheck :size="14" />{{ dashboard.statuses.DONE }} completed</span><span><Clock :size="14" />{{ dashboard.statuses.IN_PROGRESS }} in progress</span></div></div></div><div class="dashboard-metrics"><div><span>Total tasks</span><strong>{{ dashboard.total }}</strong></div><div><span>In review</span><strong>{{ dashboard.statuses.REVIEW }}</strong></div><div :class="{ 'metric-danger': dashboard.overdue>0 }"><span>Overdue</span><strong>{{ dashboard.overdue }}</strong></div><div><span>Unassigned</span><strong>{{ dashboard.unassigned }}</strong></div></div></section><section class="distribution-panel panel"><span class="eyebrow">TASK DISTRIBUTION</span><div v-if="dashboard.total" class="chart-holder"><Chart type="doughnut" :data="chartData" :options="chartOptions" aria-label="Task status distribution" /><div class="chart-center"><strong>{{ dashboard.total }}</strong><span>tasks</span></div></div><div v-else class="chart-empty">No tasks to chart yet.</div><div class="chart-legend"><div v-for="status in statuses" :key="status.value"><span :class="['status-dot',status.value.toLowerCase()]"></span><span>{{ status.label }}</span><strong>{{ dashboard.statuses[status.value] }}</strong></div></div></section><section v-if="leader" class="workload-panel panel"><div class="section-heading"><div><span class="eyebrow">PEOPLE & CAPACITY</span><h2>Member workload</h2></div><RouterLink to="/team">Your team <ArrowUpRight :size="14" /></RouterLink></div><div class="workload-table"><div class="workload-labels"><span>TEAMMATE</span><span>ACTIVE / DONE</span><span>PROGRESS</span><span>CAPACITY</span></div><div v-for="member in dashboard.members" :key="member.user.id" class="workload-row"><div class="member-identity"><span class="avatar avatar-small">{{ initials(member.user.name) }}</span><div><strong>{{ member.user.name }}</strong><span>{{ member.assigned }} assigned · {{ member.overdue }} overdue</span></div></div><span class="workload-numbers">{{ member.active }} <small>/ {{ member.completed }}</small></span><div class="list-progress"><div class="progress-track"><span :style="{width:`${member.progress}%`}"></span></div><span>{{ member.progress }}%</span></div><span :class="['workload-badge',member.workload.toLowerCase()]"><i></i>{{ member.workload }}</span></div></div><details class="workload-method"><summary>How capacity is calculated</summary><p>Active tasks score Low 1, Medium 2, High 3, Urgent 4, plus 1 when due within three days or overdue, plus up to 3 for estimated duration beyond one day. Total ≤3: Light; 4–7: Balanced; 8–11: High; ≥12: Overloaded. Average progress includes completed tasks. This is rule-based analysis.</p></details></section><section class="deadlines-panel panel"><div class="section-heading"><div><span class="eyebrow">ON THE HORIZON</span><h2>Next deadlines</h2></div><Calendar :size="17" /></div><button v-for="task in dashboard.deadlines" :key="task.id" class="deadline-row" @click="projects.openTask(task.id)"><div><strong>{{ task.title }}</strong><span>{{ task.assignee?.name || 'Unassigned' }}</span></div><div><span :class="{overdue:due(task)==='Overdue'}">{{ due(task) }}</span><time>{{ calendar(task.deadline) }}</time></div></button><div v-if="!dashboard.deadlines.length" class="compact-empty">No open tasks with deadlines. Your horizon is clear.</div></section><section class="recent-panel panel"><div class="section-heading"><div><span class="eyebrow">A SHARED RECORD</span><h2>Recent activity</h2></div><RouterLink to="/activity">View activity <ArrowUpRight :size="14" /></RouterLink></div><ActivityList :items="projects.state.activity.slice(0,5)" compact /></section></div><ProjectInsights/></ProjectState></template>
